import type { UserConfig } from 'tsdown'

/**
 * Shared build settings for every package in the monorepo.
 *
 * - ESM only, no CJS output.
 * - `dts` is generated by oxc from `isolatedDeclarations`, which keeps builds fast and forces
 *   every public export to have an explicit type.
 * - `exports` keeps `package.json#exports` in sync with the build output. The `@aspen/source`
 *   condition lets the monorepo typecheck against sources without building dependencies first.
 * - `publint` and `attw` validate the package on every build.
 */
export const baseConfig = {
	entry: ['src/index.ts'],
	format: 'esm',
	platform: 'neutral',
	target: 'es2022',
	dts: true,
	sourcemap: true,
	clean: true,
	treeshake: true,
	exports: { devExports: '@aspen/source' },
	publint: { level: 'error' },
	attw: { profile: 'esm-only', level: 'error' },
} satisfies UserConfig
